(function () {
'use strict';
var toggle = document.getElementById('navToggle');
var nav = document.getElementById('primaryNav');
function setMenu(open) {
nav.classList.toggle('is-open', open);
toggle.setAttribute('aria-expanded', String(open));
}
toggle.addEventListener('click', function () {
setMenu(toggle.getAttribute('aria-expanded') !== 'true');
});
document.addEventListener('keydown', function (event) {
if (event.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') {
setMenu(false);
toggle.focus();
}
});
document.querySelectorAll('a[href^="#"]').forEach(function (link) {
link.addEventListener('click', function () {
var target = document.getElementById(link.getAttribute('href').slice(1));
if (!target) { return; }
if (!target.hasAttribute('tabindex')) { target.setAttribute('tabindex', '-1'); }
target.focus({ preventScroll: true });
setMenu(false);
});
});
var form = document.getElementById('contactForm');
var status = document.getElementById('formStatus');
function getError(field) {
var value = field.value.trim();
if (value === '') { return 'This field is required.'; }
if (field.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
return 'Enter a valid email address, for example name@example.com.';
}
if (field.id === 'message' && value.length < 10) {
return 'Please write at least 10 characters.';
}
return '';
}
function showError(field) {
var message = getError(field);
document.getElementById(field.id + '-error').textContent = message;
field.setAttribute('aria-invalid', message ? 'true' : 'false');
return message === '';
}
var fields = form.querySelectorAll('input, textarea');
fields.forEach(function (field) {
field.addEventListener('blur', function () { showError(field); });
});
form.addEventListener('submit', function (event) {
event.preventDefault();
status.textContent = '';
var firstInvalid = null;
fields.forEach(function (field) {
if (!showError(field) && !firstInvalid) { firstInvalid = field; }
});
if (firstInvalid) {
firstInvalid.focus();
return;
}
status.textContent = 'Thank you. Your message is valid (demo form: nothing was sent).';
form.reset();
});
document.getElementById('year').textContent = new Date().getFullYear();
})();